package main

import (
	"ThroneCore/gen"
	"context"
	"sync"

	"google.golang.org/protobuf/proto"
)

// protoRPCServer keeps the current context-based Core implementation intact while
// exposing the net/rpc method signatures generated by protoc-gen-protorpc.
type protoRPCServer struct {
	probeSuccess chan struct{}
	probeOnce    sync.Once
}

var globalServer = new(server)

func adaptProtoRPC[T interface {
	proto.Message
	comparable
}](out T, call func() (T, error)) error {
	response, err := call()
	var zero T
	if response != zero {
		proto.Reset(out)
		proto.Merge(out, response)
	}
	return err
}

func (s *protoRPCServer) Start(in *gen.LoadConfigReq, out *gen.ErrorResp) error {
	return adaptProtoRPC(out, func() (*gen.ErrorResp, error) { return globalServer.Start(context.Background(), in) })
}

func (s *protoRPCServer) Stop(in *gen.EmptyReq, out *gen.ErrorResp) error {
	return adaptProtoRPC(out, func() (*gen.ErrorResp, error) { return globalServer.Stop(context.Background(), in) })
}

