func (s *protoRPCServer) SetSystemDNS(in *gen.SetSystemDNSRequest, out *gen.EmptyResp) error {
	return setSystemDNSProtoRPC(in, out)
}

func (s *protoRPCServer) IsPrivileged(in *gen.EmptyReq, out *gen.IsPrivilegedResponse) error {
	err := adaptProtoRPC(out, func() (*gen.IsPrivilegedResponse, error) {
		return globalServer.IsPrivileged(context.Background(), in)
	})
	if err == nil && s.probeSuccess != nil {
		s.probeOnce.Do(func() { close(s.probeSuccess) })
	}
	return err
}

